157:    // Computes `n CHOOSE k`, or -1 if that value is not representable as an int.
158:    public static int intSlowCautiousChoose(int n, int k) {
159:	if (k < 0 || k > n) return 0;
160:        if (k > (n >> 1)) k = n - k;
161:        if (k < 2) return (k == 0) ? 1 : n;
162:        if (n > maxIntChooseN && (k << 1) > maxIntChooseN) return -1;
163:	for (int j = 0; j < k; j++) tempIntChooseArray[j] = n - j;
164:	for (int j = k; j > 1; j--) {
165:	    // You can't just try to find an array element that j divides;
166:	    // you have to pick j apart into its prime factors.  Example: `40 CHOOSE 9`.
167:	    int q = j;
168:	    while (q > 1) {
169:		int pf = q;
170:		int newq = 1;
171:		// Find just one prime factor of q (if none found by this loop, q itself is prime).
172:		for (int p = 2; p * p <= q; p = ((p-1)|1)+2) {
173:		    // Note that p takes on the values 2, 3, 5, 7, 9, 11, 13, 15, ...
174:		    // (For maxLongChooseN/2=16, only the values 2 and 3 are needed.)
175:		    int s = q / p;
176:		    if (s*p == q) { pf = p; newq = s; break; }
177:		}
178:		// Now divide some element of the array by that prime factor
179:		found: {
180:		    for (int m = 0; m < k; m++) {
181:			int w = tempIntChooseArray[m] / pf;
182:			if (w * pf == tempIntChooseArray[m]) {
183:			    tempIntChooseArray[m] = w;
184:			    break found;
185:			}
186:		    }
187:		    System.out.println("n=" + n + ",k=" + k + ",j=" + j);
188:		    for (int z = 0; z < k; z++) System.out.println(tempIntChooseArray[z]);
189:		    throw new UnknownError("THIS SHOULDN'T HAPPEN in intSlowCautiousChoose");
190:		}
191:		q = newq;
192:	    }
193:	}
194:	int result = tempIntChooseArray[0];
195:	for (int j = 1; j < k; j++) {
196:	    result = intCautiousNonNegativeMul(result, tempIntChooseArray[j]);
197:	    if (result == -1) break;
198:	}
199:	return result;
200:    }
