202:    // This is the one we want to use from Fortress code.  It tries to be fast.
203:    public static int intOverflowingChoose(int n, int k) {
204:       	// System.out.println("Entering " + n + " CHOOSE " + k + "; array length is " + intChooseTable.length);
205:	if (k < 0 || k > n) return 0;
206:        if (k > (n >> 1)) k = n - k;
207:        if (k < 2) return (k == 0) ? 1 : n;
208:	if (n <= maxIntChooseN) return intChooseTable[chooseAccess(n, k)];
209:	if (k > maxIntChooseN)
210:	    throw Utility.makeFortressException("fortress.CompilerBuiltin$IntegerOverflow");
211:	if (n > maxIntChooseSafeN[k-2]) {
212:	    int q = intSlowCautiousChoose(n, k);
213:	    if (q == -1) throw Utility.makeFortressException("fortress.CompilerBuiltin$IntegerOverflow");
214:	    return q;
215:	}
216:	// Fast algorithm (no overflow checking required)
217:	int r = n;
218:	for (int j = 1; j < k; j++) r = (r * (n - j)) / (j + 1);
219:	return r;
220:    }
