372:	    else if (a < 0) throw Utility.makeFortressException("fortress.CompilerBuiltin$DivisionByZero");
373:	    else return 0;
374:	}
375:	long result = 1;
376:	long x = a;
377:	do {
378:	    if (x != (int) x) throw Utility.makeFortressException("fortress.CompilerBuiltin$IntegerOverflow");
379:	    if ((b & 1) != 0) {
380:		result *= x;
381:		if (result != (int) result) throw Utility.makeFortressException("fortress.CompilerBuiltin$IntegerOverflow");
382:	    }
383:	    b >>= 1;
384:	    x *= x;
385:	} while (b > 0);
386:	return (int) result;
